// Replace {{token}} placeholders in Markdown with values from the release
// manifest (src/data/release.json). The manifest is generated by
// zignos-build/release-manifest.py and published by publish-release.sh.
//
// Only text nodes are rewritten: tokens inside inline code or fenced code
// blocks stay literal so the manifest/reference pages can document them.

import { readFileSync } from 'node:fs';

const manifestUrl = new URL('../data/release.json', import.meta.url);
const release = JSON.parse(readFileSync(manifestUrl, 'utf8'));

const artifact = (name) => release.artifacts.find((a) => a.name === name) ?? {};

const values = {
  release: release.release,
  'release.name': release.release,
  'release.date': release.build_date,
  'release.channel': release.channel,
  'release.availability': release.availability,
  build_date: release.build_date,

  'stage3.revision': release.stage3.revision,
  'stage3.filename': release.stage3.filename,
  'stage3.size_mib': release.stage3.size_mib,
  'stage3.size': `${release.stage3.size_mib} MiB`,
  'stage3.sha256': release.stage3.sha256,
  'stage3.package_count': release.stage3.package_count,

  'zpkg.version': release.zpkg.version,
  'zpkg.filename': artifact('zpkg').filename ?? '',
  'zpkg.sha256': artifact('zpkg').sha256 ?? '',

  'kernel.package': release.kernel.package,
  'kernel.version': release.kernel.version,
  'kernel.revision': release.kernel.revision,
  'kernel.full': `${release.kernel.version}-r${release.kernel.revision}`,
  'bootloader.package': release.bootloader.package,
  'bootloader.version': release.bootloader.version,
  'bootloader.revision': release.bootloader.revision,
  'bootloader.full': `${release.bootloader.version}-r${release.bootloader.revision}`,

  'base.top_level': release.base.top_level,
  'base.closure': release.base.closure,

  'recipes.per_channel': release.recipes.per_channel,
  'recipes.total': release.recipes.total,
  'recipes.filename': release.recipes.filename,
  'recipes.sha256': release.recipes.sha256,

  'boot.bios': release.boot.bios,
  'boot.uefi': release.boot.uefi,
  'boot.hardware': release.boot.hardware,
};

const token = /\{\{\s*([a-zA-Z0-9_.-]+)\s*\}\}/g;

function replace(value) {
  return value.replace(token, (match, key) =>
    Object.prototype.hasOwnProperty.call(values, key) ? String(values[key]) : match,
  );
}

function walk(node) {
  if (!node || typeof node !== 'object') return;
  if (node.type === 'text' || node.type === 'inlineCode') {
    node.value = replace(node.value);
    return;
  }
  // Keep tokens in fenced code examples literal.
  if (node.type === 'code') return;
  if (Array.isArray(node.children)) {
    for (const child of node.children) walk(child);
  }
}

export default function remarkRelease() {
  return (tree) => walk(tree);
}
